import {SqliteContactRepository} from '../../../server/contact/sqlite-repository.ts';import {AttemptTokens} from '../../../server/contact/attempt-token.ts';
process.once('message',(value:unknown)=>{const data=value as {path:string;key:string;attempt:{attemptId:string;token:string};input:unknown};const repo=new SqliteContactRepository(data.path,new AttemptTokens(Buffer.from(data.key,'hex')));process.send?.('ready');process.once('message',()=>{try{process.send?.(repo.submit(data.attempt,data.input));}catch{process.send?.({result:'error'});}finally{repo.close();process.disconnect();}});});
